        sd = socket(AF_INET, SOCK_DGRAM, IPPROTO_UDP);
        if(sd < 0) std_err();

        *(u_long *)(info + 4) = (sizeof(info) - 1) - 8;
        fputs("- request informations
", stdout);
        SEND(info);
        if(timeout(sd) < 0) {
            fputs("
Error: socket timeout, no reply received

", stdout);
            exit(1);
        }
        len = recvfrom(sd, buff, BUFFSZ, 0, NULL, NULL);
        if(len < 0) std_err();

        if(len > 23) {
            len = buff[26];
            buff[27 + len] = 0x00;
