    req.bmRequestType = type;
    req.bRequest = reqno;
    req.wValue = val;
    req.wIndex = idx;
    req.wLength = strlen(msg);
    req.pData =  msg;
    req.wLenDone = 0;
    IOReturn rc = KERN_SUCCESS;
    rc = (*dev)->DeviceRequest(dev, &req);
    if(rc != KERN_SUCCESS)
        return rc;
    return KERN_SUCCESS;
